import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"ADR-0042: Transformations as First-Class Values","description":"","frontmatter":{},"headers":[],"relativePath":"handl/project/adrs/0042-transformations-as-first-class-values.md","filePath":"vendored/handl/project/adrs/0042-transformations-as-first-class-values.md"}`),a={name:`handl/project/adrs/0042-transformations-as-first-class-values.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0042-transformations-as-first-class-values" tabindex="-1">ADR-0042: Transformations as First-Class Values <a class="header-anchor" href="#adr-0042-transformations-as-first-class-values" aria-label="Permalink to “ADR-0042: Transformations as First-Class Values”">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to “Status”">​</a></h2><p>Proposed</p><p>Builds on <a href="./0041-languages-as-first-class-values.html">ADR-0041 — Languages as First-Class Values</a>.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>ADR-0041 made <code>Language</code> a first-class value and <code>eval</code> a handl-level function. The operator that worked on level N became a value at level N+1: <code>apply</code> operated on functions, so functions became values; <code>eval</code> operated on languages, so languages became values.</p><p>The next operator up is the one that operates on languages: <strong>a transformation <code>Language -&gt; Language</code> (or <code>Language -&gt; Target</code>).</strong> Compilers, translators, optimizers, desugarers, partial evaluators, capability strippers. Today these are fixed host processes — <code>cargo build</code>, <code>tsc</code>, <code>esbuild</code>. Once <code>Language</code> is a value, a transformation is just a function from values to values, and functions are already first-class.</p><p>The move is the same move, one level up again:</p><table tabindex="0"><thead><tr><th>level</th><th>what&#39;s first-class</th><th>the operator</th></tr></thead><tbody><tr><td>1</td><td>functions</td><td><code>apply : (A -&gt; B) -&gt; A -&gt; B</code></td></tr><tr><td>2</td><td>languages</td><td><code>eval : Language -&gt; Source -&gt; Value</code></td></tr><tr><td>3</td><td>transformations</td><td><code>compose : (L -&gt; L) -&gt; (L -&gt; L) -&gt; (L -&gt; L)</code></td></tr></tbody></table><p>A compiler stops being a build step and becomes a value you bind, pass, compose, and dispatch on. <code>compose(optimize, strip-io)</code> is a compiler pipeline built at runtime from two values — the same shape as <code>compose(f, g)</code> for functions.</p><h3 id="why-this-follows-from-adr-0041-not-requires-new-infrastructure" tabindex="-1">Why this follows from ADR-0041, not requires new infrastructure <a class="header-anchor" href="#why-this-follows-from-adr-0041-not-requires-new-infrastructure" aria-label="Permalink to “Why this follows from ADR-0041, not requires new infrastructure”">​</a></h3><p>ADR-0041 makes <code>Language</code> a value and <code>eval</code> a handl function. A transformation <code>Language -&gt; Language</code> is a function over a value — and functions are already first-class (level 1). So level 3 is not new machinery; it&#39;s level 1 applied to level 2. The only new thing is naming the common transformations and making them available as handl values.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Make transformations first-class handl values. A transformation is a function <code>Language -&gt; Language</code> (semantic-preserving) or <code>Language -&gt; Target</code> (compilation). Both are ordinary function values, composable via ordinary function composition.</p><h3 id="_1-transformations-are-handl-function-values" tabindex="-1">1. Transformations are handl function values <a class="header-anchor" href="#_1-transformations-are-handl-function-values" aria-label="Permalink to “1. Transformations are handl function values”">​</a></h3><div class="language-handl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">handl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span># a compiler is a value: Language -&gt; Target</span></span>
<span class="line"><span>to-wasm:    type.any = (l: type.any) -&gt; compile(l, &quot;wasm&quot;);</span></span>
<span class="line"><span>to-native:  type.any = (l: type.any) -&gt; compile(l, &quot;native&quot;);</span></span>
<span class="line"><span></span></span>
<span class="line"><span># an optimizer is a value: Language -&gt; Language</span></span>
<span class="line"><span>optimize:   type.any = (l: type.any) -&gt; language {</span></span>
<span class="line"><span>  ...l,</span></span>
<span class="line"><span>  eval: optimize-behaviors(l.eval),</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span></span></span>
<span class="line"><span># a capability stripper is a value: Language -&gt; Language</span></span>
<span class="line"><span>strip-io:   type.any = (l: type.any) -&gt; restrict(l, pure-caps);</span></span></code></pre></div><h3 id="_2-compiler-pipelines-are-function-composition" tabindex="-1">2. Compiler pipelines are function composition <a class="header-anchor" href="#_2-compiler-pipelines-are-function-composition" aria-label="Permalink to “2. Compiler pipelines are function composition”">​</a></h3><div class="language-handl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">handl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span># compose transformations — pipeline as function composition</span></span>
<span class="line"><span>pipeline: type.any = compose(to-wasm, compose(optimize, strip-io));</span></span>
<span class="line"><span>safe-wasm-handl: type.any = pipeline(handl);</span></span></code></pre></div><p><code>compose(optimize, strip-io)</code> is a compiler pipeline built at runtime from two values. No build system, no plugin chain, no fixed order. The pipeline is data, inspectable and reorderable.</p><h3 id="_3-the-category-of-languages-is-first-class" tabindex="-1">3. The category of languages is first-class <a class="header-anchor" href="#_3-the-category-of-languages-is-first-class" aria-label="Permalink to “3. The category of languages is first-class”">​</a></h3><p>Languages are objects; transformations are morphisms. The category is first-class — you can inspect it, compose in it, build functors over it.</p><div class="language-handl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">handl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span># a functor: map a transformation across a family of languages</span></span>
<span class="line"><span>lang-map: type.any = (t: type.any, langs: type.any) -&gt; {</span></span>
<span class="line"><span>  map(t, langs)</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span></span></span>
<span class="line"><span># apply one optimizer to every language in a kit family</span></span>
<span class="line"><span>optimized-family: type.any = lang-map(optimize, [handl, json-lang, toml-lang]);</span></span></code></pre></div><p>This is not imposed abstraction. It is what the values already are once languages and transformations are both first-class.</p><h3 id="_4-optimizable-optimizations" tabindex="-1">4. Optimizable optimizations <a class="header-anchor" href="#_4-optimizable-optimizations" aria-label="Permalink to “4. Optimizable optimizations”">​</a></h3><p>An optimizer is a <code>Language -&gt; Language</code> transformation, which is data. You can optimize the optimizer — specialize it for a target language, fuse two passes, dead-code-eliminate a pass that is a no-op. The meta-level is the same level, because transformations are values.</p><div class="language-handl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">handl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span># specialize an optimizer for a specific language</span></span>
<span class="line"><span>specialized-opt: type.any = specialize(optimize, handl);</span></span>
<span class="line"><span></span></span>
<span class="line"><span># fuse two passes into one</span></span>
<span class="line"><span>fused: type.any = fuse-passes(optimize, strip-io);</span></span></code></pre></div><h3 id="_5-semantic-interop-as-a-value" tabindex="-1">5. Semantic interop as a value <a class="header-anchor" href="#_5-semantic-interop-as-a-value" aria-label="Permalink to “5. Semantic interop as a value”">​</a></h3><p>A translation between two languages is a <code>Language -&gt; Language</code> function. Polyglot programming stops being &quot;two runtimes with a bridge&quot; and becomes &quot;one value that translates.&quot;</p><div class="language-handl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">handl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span># json-as-handl: a translator value</span></span>
<span class="line"><span>json-to-handl: type.any = (l: type.any) -&gt; language {</span></span>
<span class="line"><span>  ...handl,</span></span>
<span class="line"><span>  grammar: json-grammar,</span></span>
<span class="line"><span>  eval: json-eval-bridged-to-handl-eval,</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span></span></span>
<span class="line"><span># compose translations: A -&gt; B -&gt; C</span></span>
<span class="line"><span>a-to-c: type.any = compose(b-to-c, a-to-b);</span></span></code></pre></div><p>You can check, compose, and verify translations at runtime. Interop is a value, not a bridge.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><h3 id="positive" tabindex="-1">Positive <a class="header-anchor" href="#positive" aria-label="Permalink to “Positive”">​</a></h3><ul><li><strong>Composable compilers.</strong> A compiler pipeline is function composition over values, built at runtime. No build system, no fixed plugin order.</li><li><strong>Category of languages is first-class.</strong> Languages are objects, transformations are morphisms, composition is ordinary function composition. Functors over the category are <code>lang-map</code>.</li><li><strong>Optimizable optimizations.</strong> An optimizer is data; you can specialize, fuse, and dead-code-eliminate passes. The meta-level is the same level.</li><li><strong>Semantic interop as a value.</strong> A translator is a <code>Language -&gt; Language</code> function, composable and inspectable. Polyglot programming is one value, not two runtimes with a bridge.</li><li><strong>Runtime specialization.</strong> A compiler can be specialized to a specific language at runtime via ordinary partial application — the Futamura projections, now applied to transformations themselves.</li><li><strong>No new infrastructure.</strong> Level 3 is level 1 (first-class functions) applied to level 2 (first-class languages). The machinery already exists once ADR-0041 lands.</li></ul><h3 id="negative" tabindex="-1">Negative <a class="header-anchor" href="#negative" aria-label="Permalink to “Negative”">​</a></h3><ul><li><strong>Correctness is not guaranteed by composition.</strong> Composing two semantic-preserving transformations preserves semantics only if both actually preserve semantics. The type system can track that a value is a transformation, but not that it is a <em>correct</em> one. That is level 4 (proofs) — see <a href="./0043-proofs-as-first-class-values.html">ADR-0043</a>.</li><li><strong>Performance of composed transformations.</strong> Naive composition may produce intermediate <code>Language</code> values that are immediately re-transformed. Fusion and specialization mitigate, but require the optimizer-on-optimizers machinery to be built.</li><li><strong>Naming and curation.</strong> The common transformations (<code>compile</code>, <code>optimize</code>, <code>restrict</code>, <code>extend</code>, <code>merge</code>) need to be exposed as handl-callable values, not just Rust functions. This is a surface-area task, not a deep change, but it is work.</li></ul><h2 id="implementation-phases" tabindex="-1">Implementation phases <a class="header-anchor" href="#implementation-phases" aria-label="Permalink to “Implementation phases”">​</a></h2><h3 id="phase-1-—-expose-compile-as-a-handl-function" tabindex="-1">Phase 1 — Expose <code>compile</code> as a handl function <a class="header-anchor" href="#phase-1-—-expose-compile-as-a-handl-function" aria-label="Permalink to “Phase 1 — Expose compile as a handl function”">​</a></h3><p>The minimal step: <code>compile : Language -&gt; Target</code> is callable from handl. This alone gives the self-hosting bootstrap (from ADR-0041) and runtime specialization.</p><h3 id="phase-2-—-expose-the-standard-transformations" tabindex="-1">Phase 2 — Expose the standard transformations <a class="header-anchor" href="#phase-2-—-expose-the-standard-transformations" aria-label="Permalink to “Phase 2 — Expose the standard transformations”">​</a></h3><p><code>optimize</code>, <code>restrict</code>, <code>extend</code>, <code>merge</code> (from ADR-0041) are already <code>Language -&gt; Language</code> functions internally; expose them as handl values.</p><h3 id="phase-3-—-composition-and-lang-map" tabindex="-1">Phase 3 — Composition and <code>lang-map</code> <a class="header-anchor" href="#phase-3-—-composition-and-lang-map" aria-label="Permalink to “Phase 3 — Composition and lang-map”">​</a></h3><p><code>compose</code> already works for functions; ensure it works uniformly for <code>Language -&gt; Language</code> and <code>Language -&gt; Target</code>. Add <code>lang-map</code> for families of languages.</p><h3 id="phase-4-—-optimizable-optimizations" tabindex="-1">Phase 4 — Optimizable optimizations <a class="header-anchor" href="#phase-4-—-optimizable-optimizations" aria-label="Permalink to “Phase 4 — Optimizable optimizations”">​</a></h3><p>Build the pass-fusion and specialization machinery. An optimizer is data; specialize and fuse passes at runtime.</p><h3 id="phase-5-—-semantic-interop-as-values" tabindex="-1">Phase 5 — Semantic interop as values <a class="header-anchor" href="#phase-5-—-semantic-interop-as-values" aria-label="Permalink to “Phase 5 — Semantic interop as values”">​</a></h3><p>Ship translator values for common pairs (json-as-handl, toml-as-handl). Interop is a value, not a bridge.</p><h2 id="related-work" tabindex="-1">Related work <a class="header-anchor" href="#related-work" aria-label="Permalink to “Related work”">​</a></h2><ul><li><a href="./0041-languages-as-first-class-values.html">ADR-0041</a> — Languages as First-Class Values (this ADR applies level 1 to level 2)</li><li><a href="./0043-proofs-as-first-class-values.html">ADR-0043</a> — Proofs as First-Class Values (the next level: correctness of transformations)</li><li>Category theory — objects and morphisms, composition, functors</li><li>Futamura projections — specialization of interpreters into compilers, now applied to transformations themselves</li><li>LLVM pass managers — composable compiler passes, but fixed at build time, not runtime values</li></ul>`,48)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};